use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode a string for use as a URL query value (RFC 3986 unreserved set kept).
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

/// Convert seconds since the Unix epoch to a proleptic Gregorian (year, month, day).
/// Based on Howard Hinnant's `civil_from_days` algorithm.
fn civil_date(secs: u64) -> (i64, u32, u32) {
    let z = (secs / 86_400) as i64 + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + i64::from(m <= 2);
    (y, m as u32, d as u32)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;

        // Enrichment lookup on every call. The result does not feed the output,
        // and a transport failure is a value from `fetch`, so it is ignored here.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&tick.reason));
        let _ = http_client::fetch(&url);

        let (y, m, d) = civil_date(started);
        let y = y.clamp(0, 9999);
        let date = format!("{:04}-{:02}-{:02}", y, m, d);

        RunInfo { date, started }
    }
}

export!(Node);
